// === Tab: mySketch.js ===
//
// Original code by Kazuki Umeda 
// (https://github.com/Creativeguru97/YouTube_tutorial)
//
let stemm;
let rows = 60,
	cols = 80;
const {
	GUI
} = lil;
let parms, D;

function createGui() {
	const gui = new GUI();
	parms = {};
	for (let [varName, minValue, maxValue, defValue, step] of [
			['petals', 1, 20, 5, 1],
			['diameter', 20, 250, 200, 10],
			['petal_length', 0, 300, 60, 10],
			['petal_sharpness', 0.0, 10.0, 0.4, 0.1],
			['flower_height', 0, 600, 300, 10],
			['curvature_1', 0.0, 4.0, 0.8, 0.1],
			['curvature_2', 0.0, 1.0, 0.2, 0.05],
			['bumpiness', 0.0, 5.0, 2.5, 0.5],
			['bumps', 0.0, 5.0, 2.5, 0.5],
			['turns', 1, 5, 1, 1],
			['height_spread', 0, 1, 0, 0.01],
		  ['stem', -200, 400, 0, 1],
		  ['hue', 0, 360, 340, 1],
		  ['shading', 1, 2, 1.2, .1],
		]) {
		parms[varName] = defValue;
		gui.add(parms, varName, minValue, maxValue, step).onChange(makeFlower)
	}
}

function setup() {
	canvas = createCanvas(windowHeight*4/3, windowHeight, WEBGL);
	canvas.position(15, 0);
	D = max(width, height)

	colorMode(HSB, 360, 100, 100);
	angleMode(DEGREES);
	noStroke();

	createGui();
	let button = createButton('screenshot');
  button.position(933, 516)
	button.style("background-color", "#222222");
	button.size(247, 30);
  button.style("color", "#ffffff");
  button.style("font-size", "13px");

  // Call repaint() when the button is pressed.
  button.mousePressed(saver);
	makeFlower();
}

let theGeom;

function makeFlower() {

	beginGeometry()

	let {
		petals: pNum,
		diameter: fD,
		petal_length: pLen,
		petal_sharpness: pSharp,
		flower_height: fHeight,
		curvature_1: curve1,
		curvature_2: curve2,
		bumpiness: b,
		bumps: bNum,
		turns,
		height_spread,
		stem,
		hue,
		shading,
	} = parms;
  stemm = stem;
	for (let turn = 0; turn < turns; turn++) {
		let v = [];
		let h = fHeight * (1 - height_spread * turn / (turns)); // height_spread
		let dang = 90 * turn / (turns);

		for (theta = 0; theta < rows; theta += 1) {
			v.push([]);

			for (let phi = 0; phi < cols; phi += 1) {
				let ang = 360 * phi / (cols - 1);
				//if (phi == 0 && theta == 0) print ({turn,dang,ang});
				let r = (pLen * pow(abs(sin(dang + pNum / 2 * ang)), pSharp) + fD) * theta / rows;
				let x = r * cos(ang);
				let y = r * sin(ang);
				let z = vShape(h, r / 100, curve1, curve2, 1.5) - 200 +
					bumpiness(b, r / 100, bNum, phi * 360 / cols);

				let pos = createVector(x, y, z);
				v[theta].push(pos);
			}
		}

		for (let theta = 0; theta < v.length; theta++) {
			fill(hue, 100 - theta*shading, 100);
			for (let phi = 0; phi < v[theta].length; phi++) {
				if (theta < v.length - 1 && phi < v[theta].length - 1) {
					beginShape();
					vertex(v[theta][phi].x, v[theta][phi].y, v[theta][phi].z);
					vertex(v[theta + 1][phi].x, v[theta + 1][phi].y, v[theta + 1][phi].z);
					vertex(v[theta + 1][phi + 1].x, v[theta + 1][phi + 1].y, v[theta + 1][phi + 1].z);
					vertex(v[theta][phi + 1].x, v[theta][phi + 1].y, v[theta][phi + 1].z);
					endShape(CLOSE);
				}
				else if (theta < v.length - 1 && phi == v[theta].length - 1) {
					beginShape();
					vertex(v[theta][phi].x, v[theta][phi].y, v[theta][phi].z);
					vertex(v[theta][0].x, v[theta][0].y, v[theta][0].z);
					vertex(v[theta + 1][0].x, v[theta + 1][0].y, v[theta + 1][0].z);
					vertex(v[theta + 1][phi].x, v[theta + 1][phi].y, v[theta + 1][phi].z);
					endShape(CLOSE);
				}
			}
		}
	}
	theGeom = endGeometry();
}

function draw() {
	background('black');
  lights();
	lights();
	orbitControl(4, 4);
	push();
	ambientMaterial(100, 100, 40);
	rotateX(-30);
	translate(0, 400);
	cylinder(8, stemm+500);
	pop();
	rotateX(60);
	model(theGeom)
}

function vShape(A, r, a, b, c) {
	return A * pow(Math.E, -b * pow(abs(r), c)) * pow(abs(r), a);
}

function bumpiness(A, r, f, angle) {
	return 1 + A * pow(r, 2) * sin(f * angle);
}

function saver(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

